# Shared portable renderer for the KO z-score heatmaps in Figures S8-S16.
#
# The four KEGG pathway views in each composite remain manually prepared
# reference panels, as they do in Figures 7 and 8. This file reproduces the
# heatmap panels from the clean KO z-score tables generated by
# scripts/04_functional_prediction/generate_kegg_pathway_ko_z_scores.R.

# Load Packages ----
suppressPackageStartupMessages({
  library(graphics)
  library(grDevices)
  library(stats)
  library(utils)
})

supplementary_heatmap_treatment_levels <- c("CN", "VitA", "MeHg", "VitA+MeHg")

supplementary_heatmap_panel <- function(
    panel,
    cohort_label,
    batch_id,
    pathway_id,
    reference_row_order,
    expected_source_ko_count,
    omitted_nonfinite_ko_ids = character(),
    height) {
  list(
    panel = panel,
    cohort_label = cohort_label,
    batch_id = batch_id,
    pathway_id = pathway_id,
    reference_row_order = reference_row_order,
    expected_source_ko_count = expected_source_ko_count,
    omitted_nonfinite_ko_ids = omitted_nonfinite_ko_ids,
    width = 600,
    height = height
  )
}

