find_supplementary_heatmap_project_root <- function(start = getwd()) {
  path <- normalizePath(start, winslash = "/", mustWork = TRUE)

  repeat {
    markers <- c(
      file.path(path, "supplementary_figures", "figure_s8_s16_common.R"),
      file.path(
        path, "scripts", "04_functional_prediction",
        "generate_kegg_pathway_ko_z_scores.R"
      ),
      file.path(path, "results", "functional_prediction")
    )
    if (all(file.exists(markers) | dir.exists(markers))) return(path)

    parent <- dirname(path)
    if (identical(parent, path)) {
      stop("Could not locate the New_repo project root.", call. = FALSE)
    }
    path <- parent
  }
}

supplementary_heatmap_source_file <- function(project_root, panel_configuration) {
  file.path(
    project_root,
    "results", "functional_prediction",
    panel_configuration$batch_id,
    "kegg_pathway_ko_z_scores",
    paste0(
      panel_configuration$cohort_label, "_",
      panel_configuration$pathway_id, "_ko_z_scores.csv"
    )
  )
}

supplementary_heatmap_output_file <- function(
    project_root,
    figure_id,
    panel_configuration,
    output_dir = NULL) {
  if (is.null(output_dir)) {
    output_dir <- file.path(
      project_root, "supplementary_figures", paste0("Figure_", figure_id),
      "output"
    )
  }
  file.path(
    output_dir,
    paste0("Figure", figure_id, panel_configuration$panel, "_generated.png")
  )
}

supplementary_heatmap_reference_file <- function(project_root, figure_id) {
  file.path(
    project_root, "supplementary_figures", paste0("Figure_", figure_id),
    "output", paste0("Figure_", figure_id, "_FinalFigure.png")
  )
}

read_supplementary_heatmap_data <- function(project_root, panel_configuration) {
  source_file <- supplementary_heatmap_source_file(
    project_root, panel_configuration
  )
  if (!file.exists(source_file)) {
    stop("Missing supplementary heatmap source: ", source_file, call. = FALSE)
  }

  data <- utils::read.csv(
    source_file,
    check.names = FALSE,
    stringsAsFactors = FALSE,
    na.strings = c("", "NA"),
    fileEncoding = "UTF-8-BOM"
  )
  expected_columns <- c("ko_id", supplementary_heatmap_treatment_levels)
  if (!identical(names(data), expected_columns)) {
    stop(
      "The supplementary heatmap source columns must be: ",
      paste(expected_columns, collapse = ", "),
      call. = FALSE
    )
  }
  if (nrow(data) != panel_configuration$expected_source_ko_count) {
    stop(
      "Unexpected KO count in ", basename(source_file), ": expected ",
      panel_configuration$expected_source_ko_count, ", found ", nrow(data), ".",
      call. = FALSE
    )
  }
  if (anyDuplicated(data$ko_id) || any(!grepl("^K[0-9]{5}$", data$ko_id))) {
    stop("The supplementary source contains invalid or duplicated KO IDs.", call. = FALSE)
  }

  values <- as.matrix(
    data[, supplementary_heatmap_treatment_levels, drop = FALSE]
  )
  storage.mode(values) <- "double"
  nonfinite_rows <- !apply(values, 1L, function(row) all(is.finite(row)))
  omitted_ids <- data$ko_id[nonfinite_rows]
  if (!setequal(omitted_ids, panel_configuration$omitted_nonfinite_ko_ids)) {
    stop(
      "The undefined KO set changed in ", basename(source_file), ".",
      call. = FALSE
    )
  }

  data <- data[!nonfinite_rows, , drop = FALSE]
  values <- as.matrix(
    data[, supplementary_heatmap_treatment_levels, drop = FALSE]
  )
  storage.mode(values) <- "double"
  rownames(values) <- data$ko_id
  if (!setequal(rownames(values), panel_configuration$reference_row_order)) {
    stop(
      "The finite measured KO set differs from the supplied final figure.",
      call. = FALSE
    )
  }
  if (
    any(abs(rowMeans(values)) > 1e-12) ||
      any(abs(apply(values, 1L, stats::sd) - 1) > 1e-12)
  ) {
    stop(
      "Supplementary heatmap rows must have mean zero and unit sample SD.",
      call. = FALSE
    )
  }

  attr(values, "source_file") <- source_file
  attr(values, "omitted_nonfinite_ko_ids") <- omitted_ids
  values
}

orient_supplementary_heatmap_dendrogram <- function(dendrogram, row_order) {
  target_position <- setNames(seq_along(row_order), row_order)

  orient_node <- function(node) {
    if (is.leaf(node)) return(node)
    children <- lapply(node, orient_node)
    first_position <- vapply(children, function(child) {
      min(unname(target_position[labels(child)]))
    }, numeric(1))
    node[] <- children[order(first_position)]
    node
  }

  oriented <- orient_node(dendrogram)
  if (!identical(labels(oriented), row_order)) {
    stop(
      "The recorded KO order is not a legal rotation of the source dendrogram.",
      call. = FALSE
    )
  }
  oriented
}

draw_supplementary_heatmap_dendrogram <- function(
    dendrogram,
    row_centers,
    leaf_x = 14,
    root_x = 0) {
  label_y <- setNames(row_centers, labels(dendrogram))
  maximum_height <- attr(dendrogram, "height")
  if (!is.finite(maximum_height) || maximum_height <= 0) {
    stop("The KO dendrogram has no positive height.", call. = FALSE)
  }

  draw_node <- function(node) {
    if (is.leaf(node)) {
      return(c(x = leaf_x, y = unname(label_y[attr(node, "label")])))
    }
    child_coordinates <- lapply(node, draw_node)
    node_x <- leaf_x -
      attr(node, "height") / maximum_height * (leaf_x - root_x)
    child_y <- vapply(child_coordinates, `[[`, numeric(1), "y")
    graphics::segments(
      node_x, min(child_y), node_x, max(child_y),
      col = "black", lwd = 0.80
    )
    for (child in child_coordinates) {
      graphics::segments(
        node_x, child[["y"]], child[["x"]], child[["y"]],
        col = "black", lwd = 0.80
      )
    }
    c(x = node_x, y = mean(range(child_y)))
  }

  invisible(draw_node(dendrogram))
}

supplementary_heatmap_geometry <- function(height, row_count) {
  vertical <- switch(
    as.character(height),
    `300` = c(top = 14, bottom = 236, labels = 258),
    `600` = c(top = 25, bottom = 516, labels = 550),
    `1800` = c(top = 43, bottom = 1600, labels = 1630),
    stop("Unsupported supplementary heatmap height: ", height, call. = FALSE)
  )
  row_edges <- seq(vertical[["top"]], vertical[["bottom"]], length.out = row_count + 1L)
  list(
    column_edges = c(14, 111, 207, 304, 400),
    row_edges = row_edges,
    row_centers = (row_edges[-length(row_edges)] + row_edges[-1L]) / 2,
    column_label_y = unname(vertical[["labels"]])
  )
}

draw_supplementary_heatmap <- function(
    z_scores,
    panel_configuration,
    filename) {
  row_order <- panel_configuration$reference_row_order
  z_scores <- z_scores[
    row_order, supplementary_heatmap_treatment_levels, drop = FALSE
  ]
  row_count <- nrow(z_scores)
  dendrogram <- as.dendrogram(stats::hclust(stats::dist(z_scores)))
  dendrogram <- orient_supplementary_heatmap_dendrogram(
    dendrogram, row_order
  )
  geometry <- supplementary_heatmap_geometry(
    panel_configuration$height, row_count
  )

  dir.create(dirname(filename), recursive = TRUE, showWarnings = FALSE)
  png_arguments <- list(
    filename = filename,
    width = panel_configuration$width,
    height = panel_configuration$height,
    units = "px",
    res = 150,
    pointsize = 12,
    bg = "white"
  )
  if (capabilities("cairo")) png_arguments$type <- "cairo"
  do.call(grDevices::png, png_arguments)
  on.exit(grDevices::dev.off(), add = TRUE)

  graphics::par(mai = c(0, 0, 0, 0), family = "sans", xaxs = "i", yaxs = "i")
  graphics::plot.new()
  graphics::plot.window(
    xlim = c(0, panel_configuration$width),
    ylim = c(panel_configuration$height, 0),
    xaxs = "i",
    yaxs = "i"
  )

  palette <- grDevices::colorRampPalette(c("blue", "white", "red"))(15L)
  color_limit <- max(abs(z_scores))
  breaks <- seq(-color_limit, color_limit, length.out = length(palette) + 1L)
  color_index <- findInterval(z_scores, breaks, all.inside = TRUE)
  dim(color_index) <- dim(z_scores)

  for (row_index in seq_len(row_count)) {
    for (column_index in seq_along(supplementary_heatmap_treatment_levels)) {
      graphics::rect(
        xleft = geometry$column_edges[column_index],
        ybottom = geometry$row_edges[row_index],
        xright = geometry$column_edges[column_index + 1L],
        ytop = geometry$row_edges[row_index + 1L],
        col = palette[color_index[row_index, column_index]],
        border = NA
      )
    }
  }

  draw_supplementary_heatmap_dendrogram(
    dendrogram = dendrogram,
    row_centers = geometry$row_centers
  )
  row_label_cex <- if (row_count >= 50L) {
    0.62
  } else if (row_count >= 25L) {
    0.76
  } else {
    0.83
  }
  graphics::text(
    x = 425,
    y = geometry$row_centers,
    labels = row_order,
    adj = c(0, 0.5),
    cex = row_label_cex,
    col = "black",
    xpd = NA
  )
  graphics::text(
    x = c(55, 152, 248, 345),
    y = geometry$column_label_y,
    labels = supplementary_heatmap_treatment_levels,
    srt = 90,
    adj = c(1, 0.5),
    cex = 0.83,
    col = "black",
    xpd = NA
  )

  invisible(filename)
}

read_supplementary_png_dimensions <- function(filename) {
  connection <- file(filename, open = "rb")
  on.exit(close(connection), add = TRUE)
  header <- readBin(connection, what = "raw", n = 24L)
  signature <- as.raw(c(137, 80, 78, 71, 13, 10, 26, 10))
  if (length(header) < 24L || !identical(header[1:8], signature)) {
    stop("Invalid PNG signature: ", filename, call. = FALSE)
  }
  unsigned_32 <- function(bytes) {
    sum(as.numeric(as.integer(bytes)) * 256^(3:0))
  }
  c(
    width = unsigned_32(header[17:20]),
    height = unsigned_32(header[21:24])
  )
}

validate_supplementary_heatmap_output <- function(
    result,
    project_root,
    figure_id,
    panel_configuration) {
  if (!file.exists(result$file) || file.info(result$file)$size < 1000) {
    stop(
      "Figure ", figure_id, panel_configuration$panel,
      " PNG was not generated or is unexpectedly small.",
      call. = FALSE
    )
  }
  expected_dimensions <- c(
    panel_configuration$width, panel_configuration$height
  )
  if (!identical(
    unname(read_supplementary_png_dimensions(result$file)),
    unname(expected_dimensions)
  )) {
    stop(
      "Figure ", figure_id, panel_configuration$panel,
      " has unexpected PNG dimensions.",
      call. = FALSE
    )
  }

  reference_file <- supplementary_heatmap_reference_file(project_root, figure_id)
  if (!file.exists(reference_file)) {
    stop("Missing final-figure reference: ", reference_file, call. = FALSE)
  }
  expected_reference_dimensions <-
    supplementary_heatmap_configurations[[figure_id]]$reference_dimensions
  if (!identical(
    unname(read_supplementary_png_dimensions(reference_file)),
    unname(expected_reference_dimensions)
  )) {
    stop("The supplied Figure ", figure_id, " dimensions changed.", call. = FALSE)
  }
  invisible(TRUE)
}

generate_supplementary_heatmap_figure <- function(
    figure_id,
    output_dir = NULL,
    project_root = find_supplementary_heatmap_project_root()) {
  figure_id <- toupper(figure_id)
  figure_configuration <- supplementary_heatmap_configurations[[figure_id]]
  if (is.null(figure_configuration)) {
    stop("Unknown supplementary figure: ", figure_id, call. = FALSE)
  }

  results <- lapply(figure_configuration$panels, function(panel_configuration) {
    z_scores <- read_supplementary_heatmap_data(
      project_root, panel_configuration
    )
    output_file <- supplementary_heatmap_output_file(
      project_root, figure_id, panel_configuration, output_dir
    )
    draw_supplementary_heatmap(z_scores, panel_configuration, output_file)
    result <- list(
      figure_id = figure_id,
      panel = panel_configuration$panel,
      file = output_file,
      data = z_scores,
      row_order = panel_configuration$reference_row_order,
      source_file = attr(z_scores, "source_file"),
      omitted_nonfinite_ko_ids = attr(z_scores, "omitted_nonfinite_ko_ids")
    )
    validate_supplementary_heatmap_output(
      result, project_root, figure_id, panel_configuration
    )
    result
  })
  names(results) <- names(figure_configuration$panels)
  invisible(results)
}

generate_all_supplementary_heatmaps <- function(
    project_root = find_supplementary_heatmap_project_root()) {
  results <- lapply(names(supplementary_heatmap_configurations), function(figure_id) {
    generate_supplementary_heatmap_figure(
      figure_id = figure_id,
      project_root = project_root
    )
  })
  names(results) <- names(supplementary_heatmap_configurations)
  invisible(results)
}
